{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "A structurally related basic piperidine/heteroaromatic amine analogue has an absolute oral bioavailability of only 3% in humans, directly supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "AZD5423, a methoxyphenyl-containing drug with low oral bioavailability (4.4%) in healthy volunteers, supports the possibility of extensive first-pass or permeability-limited oral exposure in the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Agomelatine has absolute oral bioavailability below 5% in humans despite good absorption, illustrating that high polarity and first-pass metabolism can drive F below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Erlotinib has about 59% absolute oral bioavailability, but it lacks the query's strongly basic piperidine, primary amine, and high TPSA, so its high F transfers only weakly.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Encainide has 32 ± 7% absolute oral bioavailability and shares a basic N-methylpiperidine and methoxyphenyl motif, but its much lower polarity makes it a weaker model for the query's permeability-limited profile.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Tramadol has high absolute oral bioavailability (~68%), but it is much smaller and less polar than the query, limiting transferability of its high F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low oral bioavailability because the query combines high TPSA, low logD, and strong basic ionization, favoring poor passive permeability. The most functionally relevant low-F analogues (basic piperidine/heteroaromatic amine, F 3%; AZD5423, F ~4%; agomelatine, F <5%) outweigh high-F analogues that lack the query's polar and ionizable features. All evidence similarities are low, so confidence is limited.",
  "evidence_gaps": [
    "No direct human absolute bioavailability data for the exact query molecule.",
    "All analogue Morgan similarities are low (0.22–0.24), limiting transferability.",
    "No experimental data on efflux transporter liability, metabolic stability, or permeability for the query.",
    "High-F analogues are generally less polar and lack the query's primary amine/hydroxyl piperidine system."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

